#include <iostream>
#include <vector>

int sumar(const std::vector<int>& datos) {
    int total = 0;
    for (int valor : datos) {
        total = total + valor;
    }
    return total;
}

int main() {
    const std::vector<int> datos = {2, 4, 3};
    std::cout << sumar(datos);
    return 0;
}

#include <iostream>
#include <vector>

int contar_superiores(const std::vector<int>& datos, int limite) {
    int cuenta = 0;
    for (int valor : datos) {
        if (valor > limite) {
            ++cuenta;
        }
    }
    return cuenta;
}

int main() {
    const std::vector<int> datos = {1, 6, 3, 6};
    std::cout << contar_superiores(datos, 3);
    return 0;
}

